import { DatumUtils, ParserUtils, PlutusUtils } from '@hydra-sdk/core'
;(async () => {
	try {
		const compileCode =
			''
		const plutusScriptHex = PlutusUtils.applyParamsToScript(compileCode, [
			DatumUtils.mkBytes(ParserUtils.stringToHex('CustomNFT')).to_bytes(),
			DatumUtils.mkConstr(0, [
				DatumUtils.mkBytes('29c2fc715465f6280ef4abfb161710b0730f5142b0611f6c05a3f333cefacc75'),
				DatumUtils.mkInt('1') //
			]).to_bytes()
		])
		console.log('>>> / apply-params-to-script.ts:6 / plutusScriptHex:', plutusScriptHex)

		const spendingValidator = {
			type: 'PlutusV3',
			scriptCborHex: plutusScriptHex
		} as const
		const address = PlutusUtils.validatorToAddress(spendingValidator, 0)
		console.log('>>> / apply-params-to-script.ts:14 / address:', address)
		const policyId = PlutusUtils.mintingPolicyToId(spendingValidator)
		console.log('>>> / apply-params-to-script.ts:21 / policyId:', policyId)
	} catch (error) {
		console.error('Error applying params to script:', error)
	}
})()
